import{_ as s,C as i,o as d,c as n,a4 as t,j as l,E as r}from"./chunks/framework.BUqnS5H7.js";const w=JSON.parse('{"title":"Kafka 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/01-intro/chapter-01-what-is-kafka.md","filePath":"kafka/01-intro/chapter-01-what-is-kafka.md"}'),k={name:"kafka/01-intro/chapter-01-what-is-kafka.md"},f={"data-src-line":"26","data-src-file":"kafka/01-intro/chapter-01-what-is-kafka.md"},c={"data-src-line":"37","data-src-file":"kafka/01-intro/chapter-01-what-is-kafka.md"};function h(o,a,p,g,m,x){const e=i("SvgDiagram");return d(),n("div",null,[a[0]||(a[0]=t(`<h1 id="kafka-是什么" tabindex="-1" data-src-line="1" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Kafka 是什么 <a class="header-anchor" href="#kafka-是什么" aria-label="Permalink to &quot;Kafka 是什么&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><p data-src-line="3" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Kafka 是分布式流处理平台，本质是一个可持久化、可回溯、高吞吐的分布式追加日志。本文建立 Kafka 的全貌认知：它是什么、架构怎么分层、核心组件如何协同。</p></blockquote><h2 id="_1-一句话定义" tabindex="-1" data-src-line="5" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">1. 一句话定义 <a class="header-anchor" href="#_1-一句话定义" aria-label="Permalink to &quot;1. 一句话定义&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Apache Kafka 是分布式流处理平台，由 LinkedIn 开发，2011 年开源。它的本质是一个<strong>分布式追加日志系统</strong>——消息只能追加写入，不能修改，消费者按偏移量顺序读取。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer → [消息0][消息1][消息2][消息3]... → Consumer</span></span>
<span class="line"><span>           ──────── 追加日志（Partition）────────</span></span></code></pre></div><p data-src-line="14" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Kafka 的三重身份：</p><table tabindex="0"><thead data-src-line="16" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="16" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">身份</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="18" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="18" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">消息队列</td><td style="text-align:left;">发布/订阅模式，解耦生产者和消费者</td></tr><tr data-src-line="19" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">存储系统</td><td style="text-align:left;">持久化到磁盘，支持回溯消费</td></tr><tr data-src-line="20" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">流处理平台</td><td style="text-align:left;">Kafka Streams 实时处理数据流</td></tr></tbody></table><h2 id="_2-架构全景-两层结构" tabindex="-1" data-src-line="22" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">2. 架构全景：两层结构 <a class="header-anchor" href="#_2-架构全景-两层结构" aria-label="Permalink to &quot;2. 架构全景：两层结构&quot;">​</a></h2><p data-src-line="24" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Kafka 集群由「数据面」和「控制面」两层构成：</p>`,9)),l("p",f,[r(e,{src:"/kafka/01-basics-chapter-03-architecture.svg",alt:"Kafka 整体架构"})]),a[1]||(a[1]=t('<table tabindex="0"><thead data-src-line="28" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="28" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">层次</th><th style="text-align:left;">组成</th><th style="text-align:left;">职责</th></tr></thead><tbody data-src-line="30" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="30" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">数据面</td><td style="text-align:left;">Producer、Broker、Consumer</td><td style="text-align:left;">消息的实际生产、存储、消费</td></tr><tr data-src-line="31" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">控制面</td><td style="text-align:left;">Controller / 元数据层（KRaft / ZooKeeper）</td><td style="text-align:left;">分区 Leader 选举、元数据管理、副本协调</td></tr></tbody></table><p data-src-line="33" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">一个关键事实：<strong>控制面不处理任何业务消息</strong>。它做的事是让数据面「知道该往哪发、从哪读」。消息本身只流经数据面，但数据面每走一步都要向控制面「问路」。</p><h2 id="_3-核心组件" tabindex="-1" data-src-line="35" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">3. 核心组件 <a class="header-anchor" href="#_3-核心组件" aria-label="Permalink to &quot;3. 核心组件&quot;">​</a></h2>',3)),l("p",c,[r(e,{src:"/kafka/01-basics-chapter-02-terminology.svg",alt:"Kafka 核心组件全景图"})]),a[2]||(a[2]=t(`<h3 id="_3-1-存储模型" tabindex="-1" data-src-line="39" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">3.1 存储模型 <a class="header-anchor" href="#_3-1-存储模型" aria-label="Permalink to &quot;3.1 存储模型&quot;">​</a></h3><p data-src-line="41" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">消息的存储遵循一条层级链：<strong>Topic → Partition → Segment → RecordBatch</strong>。</p><table tabindex="0"><thead data-src-line="43" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="43" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">组件</th><th style="text-align:left;">说明</th><th style="text-align:left;">为什么需要它</th></tr></thead><tbody data-src-line="45" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="45" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Broker</td><td style="text-align:left;">Kafka 服务器节点</td><td style="text-align:left;">消息存储和请求处理的物理载体</td></tr><tr data-src-line="46" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Topic</td><td style="text-align:left;">消息的逻辑分类</td><td style="text-align:left;">让不同业务的数据隔离</td></tr><tr data-src-line="47" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Partition</td><td style="text-align:left;">Topic 的物理分片</td><td style="text-align:left;">并行读写和水平扩展的基本单位</td></tr><tr data-src-line="48" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Segment</td><td style="text-align:left;">Partition 内的日志段文件</td><td style="text-align:left;">控制删除粒度和索引大小</td></tr><tr data-src-line="49" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Offset</td><td style="text-align:left;">消息在分区内的唯一标识</td><td style="text-align:left;">消费者按 Offset 顺序读取，支持回溯</td></tr></tbody></table><p data-src-line="51" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">一个 Topic 被拆成多个 Partition，每个 Partition 是一条独立的追加日志。这个拆分带来两个直接结果：</p><table tabindex="0"><thead data-src-line="53" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="53" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">结果</th><th style="text-align:left;">含义</th></tr></thead><tbody data-src-line="55" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="55" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;"><strong>并行度</strong></td><td style="text-align:left;">一个 Topic 有几个分区，就能被几个消费者并行消费</td></tr><tr data-src-line="56" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;"><strong>顺序性</strong></td><td style="text-align:left;">顺序只在单个分区内保证，跨分区无序</td></tr></tbody></table><p data-src-line="58" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Partition 是 Kafka 水平扩展和并行的最小单位——单台 Broker 的吞吐存在上限，消息量超过单机上限时，唯一的出路是把数据拆开，分散到多台 Broker 并行写入、并行读取。</p><h3 id="_3-2-副本机制" tabindex="-1" data-src-line="60" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">3.2 副本机制 <a class="header-anchor" href="#_3-2-副本机制" aria-label="Permalink to &quot;3.2 副本机制&quot;">​</a></h3><p data-src-line="62" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">节点可能宕机，所以每个 Partition 要复制出多个副本（Replica），分布在不同 Broker 上：</p><table tabindex="0"><thead data-src-line="64" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="64" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">角色</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="66" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="66" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Leader</td><td style="text-align:left;">主副本，处理该分区的所有读写请求</td></tr><tr data-src-line="67" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Follower</td><td style="text-align:left;">从副本，从 Leader 同步数据，不处理客户端请求</td></tr><tr data-src-line="68" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">ISR</td><td style="text-align:left;">In-Sync Replicas，与 Leader 保持同步的副本集合</td></tr></tbody></table><p data-src-line="70" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><strong>读写都只走 Leader</strong>——Follower 不接收客户端读写，它只从 Leader 拉数据，作为高可用的备份。这样设计的原因：一个分区若允许多个副本同时接写，写入顺序就会分叉；Follower 若接读，又可能返回尚未同步的旧数据。让 Leader 独占读写，是最简单的一致性方案。</p><p data-src-line="72" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">ISR 是 Kafka 可靠性的核心。副本落后于 Leader 超过 <code>replica.lag.time.max.ms</code>（默认 30 秒）会被移出 ISR，追上后重新加入。<code>acks=all</code> 表示消息必须写入所有 ISR 副本才算成功。</p><h3 id="_3-3-消息的旅程" tabindex="-1" data-src-line="74" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">3.3 消息的旅程 <a class="header-anchor" href="#_3-3-消息的旅程" aria-label="Permalink to &quot;3.3 消息的旅程&quot;">​</a></h3><p data-src-line="76" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><strong>写入：Producer → 分区 Leader</strong></p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer 根据元数据定位「目标分区 Leader 所在 Broker」</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>发送请求到该 Broker</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Leader 写入本地日志，副本异步同步</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>按 acks 策略向 Producer 确认</span></span></code></pre></div><p data-src-line="91" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><strong>读取：Consumer ← 分区 Leader</strong></p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Consumer 发起 Fetch 请求</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>请求发往分区 Leader</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Broker 从日志读取，经 sendfile() 零拷贝返回</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Consumer 反序列化、处理、提交 Offset</span></span></code></pre></div><p data-src-line="106" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Producer 和 Consumer 都只与分区 Leader 打交道，Follower 是为高可用而存在的备份。</p><h3 id="_3-4-控制面-谁在支撑数据面" tabindex="-1" data-src-line="108" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">3.4 控制面：谁在支撑数据面 <a class="header-anchor" href="#_3-4-控制面-谁在支撑数据面" aria-label="Permalink to &quot;3.4 控制面：谁在支撑数据面&quot;">​</a></h3><p data-src-line="110" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Producer 和 Consumer 凭什么知道「目标分区的 Leader 在哪台 Broker」？靠的是一份由 Controller 统一维护、持续广播到全集群的元数据。这就是控制面存在的根本原因：分布式系统里，客户端不可能自己记住所有分区的 Leader 位置，必须有一个权威源统一管理并对外提供。</p><p data-src-line="112" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">早期 Controller 依赖 ZooKeeper，Kafka 4.0 起用内置的 KRaft 元数据协议取代 ZooKeeper，不再需要单独维护 ZooKeeper 集群。</p><h2 id="_4-为什么快" tabindex="-1" data-src-line="114" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">4. 为什么快 <a class="header-anchor" href="#_4-为什么快" aria-label="Permalink to &quot;4. 为什么快&quot;">​</a></h2><p data-src-line="116" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Kafka 的高吞吐来自四个机制：</p><table tabindex="0"><thead data-src-line="118" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="118" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">机制</th><th style="text-align:left;">原理</th><th style="text-align:left;">效果</th></tr></thead><tbody data-src-line="120" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="120" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">顺序写入</td><td style="text-align:left;">消息追加到日志文件末尾</td><td style="text-align:left;">顺序磁盘写比随机写快 1000 倍</td></tr><tr data-src-line="121" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">零拷贝</td><td style="text-align:left;"><code>sendfile()</code> 跳过用户态，数据从内核缓冲区直达网卡</td><td style="text-align:left;">减少 CPU 拷贝和上下文切换</td></tr><tr data-src-line="122" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">批量发送</td><td style="text-align:left;">消息攒批再发</td><td style="text-align:left;">减少网络往返与 TCP 开销</td></tr><tr data-src-line="123" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">页缓存</td><td style="text-align:left;">消息写入操作系统页缓存而非 JVM 堆</td><td style="text-align:left;">读取未落盘消息时直接从内存返回</td></tr></tbody></table><p data-src-line="125" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">深度解析见 <a href="./../04-performance/chapter-01-why-kafka-is-fast.html">为什么 Kafka 这么快</a>。</p><h2 id="_5-性能参考" tabindex="-1" data-src-line="127" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">5. 性能参考 <a class="header-anchor" href="#_5-性能参考" aria-label="Permalink to &quot;5. 性能参考&quot;">​</a></h2><p data-src-line="129" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">Benchmark 数据依赖消息大小、压缩、副本因子、硬件与网络，只能作为上界参考。</p><table tabindex="0"><thead data-src-line="131" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="131" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">场景</th><th style="text-align:left;">吞吐量</th><th style="text-align:left;">来源</th></tr></thead><tbody data-src-line="133" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="133" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">单生产者，无副本</td><td style="text-align:left;">82 万条/秒</td><td style="text-align:left;"><a href="https://engineering.linkedin.com/kafka/benchmarking-apache-kafka-2-million-writes-second-three-cheap-machines" target="_blank" rel="noreferrer">LinkedIn 2014</a></td></tr><tr data-src-line="134" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">3 生产者，3 副本异步</td><td style="text-align:left;">202 万条/秒</td><td style="text-align:left;">同上</td></tr><tr data-src-line="135" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">端到端延迟</td><td style="text-align:left;">中位 2ms，p99 3ms</td><td style="text-align:left;">同上</td></tr><tr data-src-line="136" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Kafka 峰值吞吐</td><td style="text-align:left;">605 MB/s</td><td style="text-align:left;"><a href="https://www.confluent.io/blog/kafka-fastest-messaging-system/" target="_blank" rel="noreferrer">Confluent 2020</a></td></tr><tr data-src-line="137" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">Pulsar 峰值吞吐</td><td style="text-align:left;">305 MB/s</td><td style="text-align:left;">同上</td></tr><tr data-src-line="138" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">RabbitMQ 峰值吞吐</td><td style="text-align:left;">38 MB/s</td><td style="text-align:left;">同上</td></tr></tbody></table><h2 id="_6-典型使用场景" tabindex="-1" data-src-line="140" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">6. 典型使用场景 <a class="header-anchor" href="#_6-典型使用场景" aria-label="Permalink to &quot;6. 典型使用场景&quot;">​</a></h2><table tabindex="0"><thead data-src-line="142" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="142" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><th style="text-align:left;">场景</th><th style="text-align:left;">说明</th><th style="text-align:left;">代表用户</th></tr></thead><tbody data-src-line="144" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><tr data-src-line="144" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">日志收集</td><td style="text-align:left;">应用日志 → Kafka → ELK</td><td style="text-align:left;">LinkedIn、Netflix</td></tr><tr data-src-line="145" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">事件驱动</td><td style="text-align:left;">服务间异步通信</td><td style="text-align:left;">Uber、Airbnb</td></tr><tr data-src-line="146" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">数据管道</td><td style="text-align:left;">MySQL → Debezium → Kafka → 数仓</td><td style="text-align:left;">大多数数据团队</td></tr><tr data-src-line="147" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">流式处理</td><td style="text-align:left;">Kafka → Flink/Streams → 结果</td><td style="text-align:left;">实时风控、推荐</td></tr><tr data-src-line="148" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><td style="text-align:left;">指标监控</td><td style="text-align:left;">应用指标 → Kafka → Prometheus</td><td style="text-align:left;">运维监控</td></tr></tbody></table><h2 id="_7-下一步" tabindex="-1" data-src-line="150" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">7. 下一步 <a class="header-anchor" href="#_7-下一步" aria-label="Permalink to &quot;7. 下一步&quot;">​</a></h2><ul data-src-line="152" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md"><li data-src-line="152" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">不确定 Kafka 是否适合你的场景？→ <a href="./chapter-03-mq-comparison.html">消息队列选型</a></li><li data-src-line="153" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">想系统学习？→ <a href="./chapter-02-learning-path.html">学习路径</a></li><li data-src-line="154" data-src-file="kafka/01-intro/chapter-01-what-is-kafka.md">想深入某个主题？→ 从 <code>02-core/</code> 目录开始，每个文档聚焦一个核心概念</li></ul>`,31))])}const b=s(k,[["render",h]]);export{w as __pageData,b as default};
